14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if cursor == target_cursor {
53	            return complete_arg(
54	                &arg,
55	                current_cmd,
56	                current_dir,
57	                pos_index,
58	                is_escaped,
59	                current_state,
60	                &used_args,
61	            );
62	        }
63	
64	        if let Ok(value) = arg.to_value() {
65	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
66	                current_cmd = next_cmd;
67	                pos_index = 1;
68	                used_args.clear();
69	                continue;
70	            }
71	        }
72	
73	        if is_escaped {
74	            (next_state, pos_index) =
75	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
76	        } else if arg.is_escape() {
77	            is_escaped = true;
78	        } else if opt_allows_hyphen(&current_state, &arg) {
79	            match current_state {
80	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
81	                _ => unreachable!("else branch is only reachable in Opt state"),
82	            }
83	        } else if let Some((flag, value)) = arg.to_long() {
84	            if let Ok(flag) = flag {
85	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
86	
87	                if let Some(opt) = opt {
88	                    used_args.push(opt.get_id().clone());
89	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
90	                        next_state = ParseState::Opt((opt, 1));
91	                    };
92	                } else if pos_allows_hyphen(current_cmd, pos_index) {
93	                    (next_state, pos_index) =
94	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
95	                }
96	            }
97	        } else if let Some(short) = arg.to_short() {
98	            let (_, matched_opts, takes_value_opt, mut short) =
99	                parse_shortflags(current_cmd, short);
100	            used_args.extend(matched_opts.iter().map(|opt| opt.get_id().clone()));
101	            if let Some(opt) = takes_value_opt {
102	                if short.next_value_os().is_none() {
103	                    next_state = ParseState::Opt((opt, 1));
104	                }
105	            } else if pos_allows_hyphen(current_cmd, pos_index) {
106	                (next_state, pos_index) =
107	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
108	            }
109	        } else {
110	            match current_state {
111	                ParseState::ValueDone | ParseState::Pos(..) => {
112	                    (next_state, pos_index) =
113	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
114	                }
115	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
116	            }
117	        }
118	    }
119	
120	    Err(std::io::Error::other("no completion generated"))
121	}
