135	fn complete_arg(
136	    arg: &clap_lex::ParsedArg<'_>,
137	    cmd: &clap::Command,
138	    current_dir: Option<&std::path::Path>,
139	    pos_index: usize,
140	    is_escaped: bool,
141	    state: ParseState<'_>,
142	    used_args: &[clap::Id],
143	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
144	    debug!(
145	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
146	        arg,
147	        cmd.get_name(),
148	        current_dir,
149	        pos_index,
150	        state
151	    );
152	    let mut completions = Vec::<CompletionCandidate>::new();
153	
154	    match state {
155	        ParseState::ValueDone => {
156	            if let Ok(value) = arg.to_value() {
157	                completions.extend(complete_subcommand(value, cmd));
158	            }
159	
160	            if let Some(positional) = cmd
161	                .get_positionals()
162	                .find(|p| p.get_index() == Some(pos_index))
163	            {
164	                completions.extend(complete_arg_value(
165	                    arg.to_value(),
166	                    positional,
167	                    current_dir,
168	                    0,
169	                ));
170	            }
171	            if !is_escaped {
172	                completions.extend(complete_option(arg, cmd, current_dir));
173	            }
174	        }
175	        ParseState::Pos((_, num_arg)) => {
176	            if let Some(positional) = cmd
177	                .get_positionals()
178	                .find(|p| p.get_index() == Some(pos_index))
179	            {
180	                completions.extend(complete_arg_value(
181	                    arg.to_value(),
182	                    positional,
183	                    current_dir,
184	                    num_arg.saturating_sub(1),
185	                ));
186	                if !is_escaped
187	                    && positional
188	                        .get_num_args()
189	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
190	                {
191	                    completions.extend(complete_option(arg, cmd, current_dir));
192	                }
193	            }
194	        }
195	        ParseState::Opt((opt, count)) => {
196	            completions.extend(complete_arg_value(
197	                arg.to_value(),
198	                opt,
199	                current_dir,
200	                count.saturating_sub(1),
201	            ));
202	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
203	            if count > min {
204	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
205	                completions.extend(complete_arg(
206	                    arg,
207	                    cmd,
208	                    current_dir,
209	                    pos_index,
210	                    is_escaped,
211	                    ParseState::ValueDone,
212	                    used_args,
213	                )?);
214	            }
215	        }
216	    }
217	    filter_conflicting_candidates(&mut completions, cmd, used_args);
218	    if completions.iter().any(|a| !a.is_hide_set()) {
219	        completions.retain(|a| !a.is_hide_set());
220	    }
221	    let mut seen_ids = std::collections::HashSet::new();
222	    completions.retain(move |a| {
223	        if let Some(id) = a.get_id().cloned() {
224	            seen_ids.insert(id)
225	        } else {
226	            true
227	        }
228	    });
229	
230	    let mut tags = Vec::new();
231	    for candidate in &completions {
232	        let tag = candidate.get_tag().cloned();
233	        if !tags.contains(&tag) {
234	            tags.push(tag);
235	        }
236	    }
237	    completions.sort_by_key(|c| {
238	        (
239	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
240	            c.get_display_order(),
241	        )
242	    });
243	
244	    Ok(completions)
245	}
